/bin/bash -lc "python3 - <<'PY'
import zipfile, io, openpyxl
z=zipfile.ZipFile('/workspace/Ke_SI_tables.zip')
for name in ['Ke et al_Table S5_FINAL.xlsx','Ke et al_Table S6_FINAL.xlsx','Ke et al_Table S7_FINAL.xlsx','Ke et al_Table S3_FINAL.xlsx']:
 wb=openpyxl.load_workbook(io.BytesIO(z.read(name)), data_only=True)
 print('\\n===',name)
 for ws in wb.worksheets:
  print('SHEET',ws.title,ws.max_row,ws.max_column)
  for row in ws.iter_rows(min_row=1,max_row=min(ws.max_row,12),values_only=True): print(row)
PY"

