import zipfile, io, openpyxl
z=zipfile.ZipFile('/workspace/Ke_SI_tables.zip')
wb=openpyxl.load_workbook(io.BytesIO(z.read('Ke et al_Table S5_FINAL.xlsx')), data_only=True)
ws=wb['Table S5']
cur=None
data={}
for row in ws.iter_rows(min_row=2,values_only=True):
 ct=row[0]
 if ct: cur=ct.strip()
