/bin/bash -lc "python3 - <<'PY'
import gzip, math, csv
markers={}
with open('/workspace/markers_top100.tsv') as f:
 r=csv.reader(f, delimiter='\\t'); next(r)
 for g,ct in r: markers.setdefault(ct,[]).append(g)
cells=None; genes=[]; D=[]
with gzip.open('inputs/sample.swap.rna.q2.tsv.gz','rt') as f:
 for i,line in enumerate(f):
  p=line.rstrip('\\n').split('\\t')
  if i==0: cells=p[1:]; continue
  genes.append(p[0]); D.append([float(x) for x in p[1:]])
idx={g:i for i,g in enumerate(genes)}
for j,cell in enumerate(cells):
 scores=[]
 for ct,gs in markers.items():
  vals=[math.log2(D[idx[g]][j]+1) for g in gs if g in idx]
  if vals: scores.append((ct,sum(vals)/len(vals)))
 scores.sort(key=lambda x:-x[1])
 print(cell, scores[0], scores[1])
PY"

